INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(40561, 'Exodus 28:10', 'Exodus', 28, 10, 'یعنې د هغوی د عمر په ترتیب، شپږ نومونه په یوه تیږه باندې او پاتې شپږ په بله تیږه باندې.', 'یعنې د هغوی د عمر په ترتیب، شپز نومونه په یوه تیزه باندې او پاتې شپز په بله تیزه باندې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_28_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40562, 'Exodus 28:11', 'Exodus', 28, 11, 'د یعقوب د زامنو د نومونو نقش په دوو تیږو باندې داسې وباسه لکه څنګه چې د غمي جوړوونکی د یو مهر نقش وباسي. بیا تیږې په هغو ځایونو کې ولګوه چې د سرو زرو د قابونو په شان جوړ شوي دي.', 'د یعقوب د زامنو د نومونو نقش په دوو تیزو باندې داسې وباسه لکه چنګه چې د غمی جوروونکی د یو مهر نقش وباسی. بیا تیزې په هغو جایونو کې ولګوه چې د سرو زرو د قابونو په شان جور شوی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_28_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40563, 'Exodus 28:12', 'Exodus', 28, 12, 'هغه تیږې د سپېڅلي پېشبند د اوږې په تسمو باندې ولګوه چې د اسراییلو د دولسو قبیلو استازیتوب وکړي. په دې ډول به هارون د هغوی نومونه په خپلو اوږو باندې انتقالوي، ترڅو زه څښتن تل خپل قوم په یاد وساتم.', 'هغه تیزې د سپېچلی پېشبند د اوزې په تسمو باندې ولګوه چې د اسراییلو د دولسو قبیلو استازیتوب وکری. په دې دول به هارون د هغوی نومونه په خپلو اوزو باندې انتقالوی، ترچو زه چشتن تل خپل قوم په یاد وساتم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_28_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40564, 'Exodus 28:13', 'Exodus', 28, 13, 'د سرو زرو د قابونو په شان دوه ځایونه جوړ کړه', 'د سرو زرو د قابونو په شان دوه جایونه جور کره', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_28_13.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40565, 'Exodus 28:14', 'Exodus', 28, 14, 'او دوه د سوچه سرو زرو تاو شوي زنځیرونه د یوې رسۍ په شان جوړ کړه او په هغو ځایونو کې یې ولګوه.', 'او دوه د سوچه سرو زرو تاو شوی زنجیرونه د یوې رسی په شان جور کره او په هغو جایونو کې یې ولګوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_28_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40566, 'Exodus 28:15', 'Exodus', 28, 15, 'د لوی کاهن دپاره سینه پوښ جوړ کړه چې د خدای د رضا د معلومولو دپاره ورڅخه کار واخلي. هغه دې د هماغو موادو څخه جوړ شي چې سپېڅلی پېشبند ورڅخه جوړ شوی دی او هماغسې ګلدوزي دې په کې وشي.', 'د لوی کاهن دپاره سینه پوش جور کره چې د خدای د رضا د معلومولو دپاره ورچخه کار واخلی. هغه دې د هماغو موادو چخه جور شی چې سپېچلی پېشبند ورچخه جور شوی دی او هماغسې ګلدوزی دې په کې وشی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40567, 'Exodus 28:16', 'Exodus', 28, 16, 'هغه دې څلور کنجه وي، دوه ویشت سانتي دې اوږد وي او دوه ویشت سانتي دې پلن وي او دوه قاته دې وي.', 'هغه دې چلور کنجه وی، دوه ویشت سانتی دې اوزد وی او دوه ویشت سانتی دې پلن وی او دوه قاته دې وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40568, 'Exodus 28:17', 'Exodus', 28, 17, 'بیا په هغه باندې څلور قطاره قیمتي تیږې ولګوه. په لومړي قطار کې یو یاقوت، یو زیړ یاقوت او یو لعل ولګوه.', 'بیا په هغه باندې چلور قطاره قیمتی تیزې ولګوه. په لومری قطار کې یو یاقوت، یو زیر یاقوت او یو لعل ولګوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40569, 'Exodus 28:18', 'Exodus', 28, 18, 'په دوهم قطار کې یو زمرد، یوه د لاجوردو تیږه او یو الماس ولګوه.', 'په دوهم قطار کې یو زمرد، یوه د لاجوردو تیزه او یو الماس ولګوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_18.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40570, 'Exodus 28:19', 'Exodus', 28, 19, 'په درېم قطار کې یوه فیروزه، یو سپین عقیق او یو بانجاني یاقوت ولګوه', 'په درېم قطار کې یوه فیروزه، یو سپین عقیق او یو بانجانی یاقوت ولګوه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_19.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40571, 'Exodus 28:20', 'Exodus', 28, 20, 'او په څلورم قطار کې یو شینکی یاقوت، د عقیقو یوه تیږه او یو کوارتز ولګوه. هغه دې په داسې ځایونو کې ولګول شي چې د سرو زرو د قابونو په شان جوړ شوي دي.', 'او په چلورم قطار کې یو شینکی یاقوت، د عقیقو یوه تیزه او یو کوارتز ولګوه. هغه دې په داسې جایونو کې ولګول شی چې د سرو زرو د قابونو په شان جور شوی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40572, 'Exodus 28:21', 'Exodus', 28, 21, 'دولس تیږې دې وي، د یعقوب د زامنو د هر نوم دپاره یوه یوه تیږه. په هرې یوې کې دې د یو مهر په شان نقش وويستل شي او د دولسو قبیلو څخه دې د یوې قبیلې نوم په کې وي.', 'دولس تیزې دې وی، د یعقوب د زامنو د هر نوم دپاره یوه یوه تیزه. په هرې یوې کې دې د یو مهر په شان نقش وویستل شی او د دولسو قبیلو چخه دې د یوې قبیلې نوم په کې وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40573, 'Exodus 28:22', 'Exodus', 28, 22, 'د سینه پوښ دپاره د سوچه سرو زرو څخه داسې زنځیرونه جوړ کړه چې د یوې رسۍ په شان تاو شوي وي.', 'د سینه پوش دپاره د سوچه سرو زرو چخه داسې زنجیرونه جور کره چې د یوې رسی په شان تاو شوی وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_28_22.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40574, 'Exodus 28:23', 'Exodus', 28, 23, 'دوه د سرو زرو کړۍ ګانې جوړې کړه او د سینه پوښ په پورتنیو کنجونو یې ونښلوه', 'دوه د سرو زرو کری ګانې جورې کره او د سینه پوش په پورتنیو کنجونو یې ونشلوه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40575, 'Exodus 28:24', 'Exodus', 28, 24, 'او په دغو دوو کړیو باندې دوه د سرو زرو زنځیرونه وتړه.', 'او په دغو دوو کریو باندې دوه د سرو زرو زنجیرونه وتره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40576, 'Exodus 28:25', 'Exodus', 28, 25, 'د زنځیرونو دوه نور سرونه د هغو ځایونو پورې وتړه چې د سرو زرو څخه جوړ شویو قابونو په شان دي او په دې ډول یې د سپېڅلي پېشبند د اوږې د تسمو په مخکینۍ برخې باندې ونښلوه.', 'د زنجیرونو دوه نور سرونه د هغو جایونو پورې وتره چې د سرو زرو چخه جور شویو قابونو په شان دی او په دې دول یې د سپېچلی پېشبند د اوزې د تسمو په مخکینی برخې باندې ونشلوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_25.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40577, 'Exodus 28:26', 'Exodus', 28, 26, 'بیا د سرو زرو دوه کړۍ ګانې جوړې کړه او د سینه پوښ په لاندېنیو کنجونو پورې یې ونښلوه. هغه دې په دنننۍ څنډې باندې د سپېڅلي پېشبند په څنګ کې وي.', 'بیا د سرو زرو دوه کری ګانې جورې کره او د سینه پوش په لاندېنیو کنجونو پورې یې ونشلوه. هغه دې په دنننی چندې باندې د سپېچلی پېشبند په چنګ کې وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_26.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40578, 'Exodus 28:27', 'Exodus', 28, 27, 'دوه نورې کړۍ ګانې جوړې کړه او د اوږې د تسمو په لاندېنۍ برخه کې یې ونښلوه چې د سپېڅلي پېشبند په مخکینۍ برخې باندې بخۍ ته نژدې او د سپېڅلي پېشبند د کمربند دپاسه دي.', 'دوه نورې کری ګانې جورې کره او د اوزې د تسمو په لاندېنی برخه کې یې ونشلوه چې د سپېچلی پېشبند په مخکینی برخې باندې بخی ته نژدې او د سپېچلی پېشبند د کمربند دپاسه دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40579, 'Exodus 28:28', 'Exodus', 28, 28, 'د سینه پوښ کړۍ ګانې دې د سپېڅلي پېشبند د کړۍ ګانو سره چې د کمربند سره وصل دي په ابي مزي باندې وتړل شي، ترڅو سینه پوښ د سپېڅلي پېشبند څخه لېرې نه شي.', 'د سینه پوش کری ګانې دې د سپېچلی پېشبند د کری ګانو سره چې د کمربند سره وصل دی په ابی مزی باندې وترل شی، ترچو سینه پوش د سپېچلی پېشبند چخه لېرې نه شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40580, 'Exodus 28:29', 'Exodus', 28, 29, 'هرکله چې هارون سپېڅلي ځای ته ورننوځي، هغه به هغه سینه پوښ اغوندي چې د اسراییلو د قبیلو نومونه ورباندې لیکل شوي دي. هغه به دا نومونه د خپل زړه دپاسه وړي، ترڅو زه څښتن تل خپل قوم رایادوم.', 'هرکله چې هارون سپېچلی جای ته ورننوجی، هغه به هغه سینه پوش اغوندی چې د اسراییلو د قبیلو نومونه ورباندې لیکل شوی دی. هغه به دا نومونه د خپل زره دپاسه وری، ترچو زه چشتن تل خپل قوم رایادوم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40581, 'Exodus 28:30', 'Exodus', 28, 30, 'اوریم او تمیم په سینه پوښ کې د هغه د زړه دپاسه کېږده. نو کله چې هارون زما پاک حضور ته راځي، هغه به یې وړي. په داسې وختونو کې باید هغه تل دا سینه پوښ واغوندي، ترڅو د اسراییلو د قوم دپاره زما رضا معلومه کړي.', 'اوریم او تمیم په سینه پوش کې د هغه د زره دپاسه کېزده. نو کله چې هارون زما پاک حضور ته راجی، هغه به یې وری. په داسې وختونو کې باید هغه تل دا سینه پوش واغوندی، ترچو د اسراییلو د قوم دپاره زما رضا معلومه کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_30.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40582, 'Exodus 28:31', 'Exodus', 28, 31, 'هغه چپنه چې د سپېڅلي پېشبند لاندې اغوستل کیږي، هغه ټوله دې د ابي ټوټې څخه جوړه شي.', 'هغه چپنه چې د سپېچلی پېشبند لاندې اغوستل کیزی، هغه توله دې د ابی توتې چخه جوره شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_31.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40583, 'Exodus 28:32', 'Exodus', 28, 32, 'د هغې په منځ کې دې د سر دپاره یو سوری پرېښودل شي او د سوري ګردچاپېره دې یوه غاړه وګنډل شي، ترڅو چپنه ونه شلیږي.', 'د هغې په منج کې دې د سر دپاره یو سوری پرېشودل شی او د سوری ګردچاپېره دې یوه غاره وګندل شی، ترچو چپنه ونه شلیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_32.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40584, 'Exodus 28:33', 'Exodus', 28, 33, 'د چپنې د لمنې په څنډه باندې د ابي، بانجاني او سرو وړیو څخه داسې انار جوړ کړه چې په منځ کې یې د سرو زرو زنګونه وي.', 'د چپنې د لمنې په چنده باندې د ابی، بانجانی او سرو وریو چخه داسې انار جور کره چې په منج کې یې د سرو زرو زنګونه وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_28_33.mp3', 'https://drive.google.com/uc?id=1CR5s4RmYjpe4j0PWwSEW5UC_ClEl5s2M&export=download', 1761237841, 1761237841),
(40585, 'Exodus 28:34', 'Exodus', 28, 34, 'د سرو زرو زنګونه او انار دې د چپنې د لمنې ګردچاپېره د یو بل ترمنځ راشي.', 'د سرو زرو زنګونه او انار دې د چپنې د لمنې ګردچاپېره د یو بل ترمنج راشی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_28_34.mp3', 'https://drive.google.com/uc?id=1RO46CUzemXznEljEfxT584h40uifFa3w&export=download', 1761237841, 1761237841),
(40586, 'Exodus 28:35', 'Exodus', 28, 35, 'هارون دې د کاهن په توګه د خدمت کولو په وخت کې دغه چپنه واغوندي. کله چې هغه زما حضور ته په سپېڅلي ځای کې راننوځي یا کله چې هغه ځي، د زنګونو اواز به اورېدل کیږي او هغه به نه وژل کیږي.', 'هارون دې د کاهن په توګه د خدمت کولو په وخت کې دغه چپنه واغوندی. کله چې هغه زما حضور ته په سپېچلی جای کې راننوجی یا کله چې هغه جی، د زنګونو اواز به اورېدل کیزی او هغه به نه وژل کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_35.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40587, 'Exodus 28:36', 'Exodus', 28, 36, 'د سوچه سرو زرو څخه یو ګل جوړ کړه او په هغه باندې د دې لغتونو یعنې ‹څښتن ته وقف شوی› یو نقش وباسه لکه څنګه چې په یو مهر باندې ویستل کیږي.', 'د سوچه سرو زرو چخه یو ګل جور کره او په هغه باندې د دې لغتونو یعنې ‹چشتن ته وقف شوی› یو نقش وباسه لکه چنګه چې په یو مهر باندې ویستل کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_28_36.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40588, 'Exodus 28:37', 'Exodus', 28, 37, 'هغه ګل په یو ابي مزي باندې د لونګۍ په مخکینۍ برخې پورې وتړه.', 'هغه ګل په یو ابی مزی باندې د لونګی په مخکینی برخې پورې وتره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_28_37.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40589, 'Exodus 28:38', 'Exodus', 28, 38, 'هارون دې هغه په خپل تندي باندې وتړي، ترڅو زه څښتن هغه ټولې سپېڅلې نذرانې چې اسراییلیان یې ماته وقف کوي قبولې کړم، حتی که چېرې خلک د هغو په وړاندې کولو کې کومه سهوه هم وکړي.', 'هارون دې هغه په خپل تندی باندې وتری، ترچو زه چشتن هغه تولې سپېچلې نذرانې چې اسراییلیان یې ماته وقف کوی قبولې کرم، حتی که چېرې خلک د هغو په وراندې کولو کې کومه سهوه هم وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_38.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(40590, 'Exodus 28:39', 'Exodus', 28, 39, 'د هارون دپاره د ښه کتان څخه کمیس او یوه لونګۍ جوړ کړه. پټۍ هم جوړه کړه او هغه دې ګلدوزي شي.', 'د هارون دپاره د شه کتان چخه کمیس او یوه لونګی جور کره. پتی هم جوره کره او هغه دې ګلدوزی شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_28_39.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(40591, 'Exodus 28:40', 'Exodus', 28, 40, 'د هارون د زامنو دپاره کمیسونه، پټۍ ګانې او خولۍ ګانې جوړې کړه چې هغوی ته عزت او ښکلا ورکړي.', 'د هارون د زامنو دپاره کمیسونه، پتی ګانې او خولی ګانې جورې کره چې هغوی ته عزت او شکلا ورکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_28_40.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
